@spec picker_publish_spec  src=tests/specs/picker_publish_spec.lua  loc=149  cases=5
@harness   mk

# Intent
  Chrome-level pin for drawPicker's onPublish hook (chain surface). Real chrome over a fake imgui:
  a row the item list marks `publishable` grows a trailing ↑, placed left of the ×, two-press as the
  × is -- and the two share one armed slot per picker kind, so arming either disarms the other.
  Recipe from picker_delete_spec, with an InvisibleButton answering to both tags and a SameLine that
  records the offset each button was placed at.

# Helpers
  @fn mkChrome(h)  @ 63-66
  @fn frame(chrome, click, opts)  @ 74-87
      -- One Load picker frame, clicking the button tagged `click` ('pub1', 'del2', ...; nil clicks
      -- nothing). Returns what fired -- { action, key } -- and the buttons drawn this frame.
  @fn buttonAt(buttons, tag)  @ 89-91

# Cases
  @case 'only a publishable row grows a ↑'  [harness]  @ 95-101
  @case 'the first click arms the ↑ and the second publishes the row'  [harness]  @ 105-118
  @case 'a picker without onPublish draws no ↑ even on a publishable row'  [harness]  @ 122-127
  @case 'the ↑ sits left of the ×, which keeps the flush-right slot'  [harness]  @ 131-136
  @case 'the two glyphs share one armed slot, so arming either disarms the other'  [harness]  @ 140-147

